define({"topics":[{"title":"System Gain Calibration","href":"t_System-Gain-Calibration_16034478.html","menu":{"hasChildren":true},"tocID":"tocId-d46e4807","next":"tocId-d46e4807"},{"title":"B0 Drift tool","href":"t_B0DriftTool_Parent.html","attributes":{"data-id":"id_2001624"},"menu":{"hasChildren":true},"tocID":"id_2001624-d46e5021","next":"id_2001624-d46e5021"},{"title":"Doing DQA calibration with the DQA III phantom","shortdesc":"<p class=\"shortdesc\">The DQA tool determines correct gradient polarity and correct gradient wiring by scanning a series of axial and coronal images of the DQA III phantom for systems below sentence MR 31.0 or sites that do not have a 17cm Sphere with Spout (SWS) phantom.<\/p>","href":"t_DoingDQACalibration.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e5538","topics":[]},{"title":"Doing DQA calibration <span class=\"ph\">with the Sphere With Spout (SWS) phantom<\/span>","shortdesc":"<p class=\"shortdesc\">Details the steps needed to run the Gradient Calibration Tool (GCT) for systems running MR31.0 and higher<span class=\"ph\"> and that possess the 17cm Sphere with Spout (SWS) phantom<\/span>. GCT does the same checks and produces the same output as DQA.<\/p>","href":"t_DoingDQACalibrationsforMR31andHigher.html","attributes":{"data-id":"id_2068424"},"menu":{"hasChildren":false},"tocID":"id_2068424-d46e5643","topics":[]},{"title":"Doing the Echo Planar Test","href":"t_DoingTheEchoPlanarTestEPT.html","attributes":{"data-id":"id_2001633"},"menu":{"hasChildren":true},"tocID":"id_2001633-d46e5754","next":"id_2001633-d46e5754"},{"title":"Calibrating LVShim","shortdesc":"<p class=\"shortdesc\">The objective of the LVShim tool is to fine-tune magnet homogeneity.<\/p>","href":"t_CalibratingLVShim.html","attributes":{"data-id":"id_2002769"},"menu":{"hasChildren":true},"tocID":"id_2002769-d46e6163","next":"id_2002769-d46e6163"},{"title":"RAD Cal Tool","shortdesc":"<p class=\"shortdesc\">Procedures for the Radial Acquisition Delay Calibration (RAD Cal) Tool, which is used to characterize the system RF delay to optimize Zero TE (ZTE) sequence image quality.<\/p>","href":"t_RAD-Cal-Tool_16498419.html","attributes":{"data-id":"id_15271074"},"menu":{"hasChildren":false},"tocID":"id_15271074-d46e6695","topics":[]},{"title":"Dual drive quadrature tool","shortdesc":"<p class=\"shortdesc\">The dual drive (DD) quadrature tool is used to compensate for the amplitude and phase differences in the transmit channels. <\/p>","href":"c_Dual-Drive-Quadrature-Tool_16504235.html#id_15271115","attributes":{"data-id":"id_15271115"},"menu":{"hasChildren":true},"tocID":"id_15271115-d46e6801","next":"id_15271115-d46e6801"}]});